use super::*;
#[derive(crate::RetireOwned,crate::NativeReceive)]#[value(crate="crate")]struct OriginalEmptyRecord{}
#[test]
fn original_empty_record_receiving_matches_serde_and_retains_every_cancelled_prefix(){let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🔗️sealed-shared-receiver/🧪️tests/🫙️empty/🧫️fixtures/🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){let accepted=case["accepted"].as_bool().unwrap();assert_eq!(serde_json::from_value::<std::collections::BTreeMap<String,serde::de::IgnoredAny>>(case["input"].clone()).is_ok_and(|fields|fields.is_empty()),accepted);for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let mut bank=bank();let original=source(DslValue::from(&case["input"]),&mut bank);let(mut receiver,h)=crate::observe_retirement_allocations(<OriginalEmptyRecord as NativeReceive<DslValue>>::receiver);assert_eq!(h,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut refused=false;for _ in 0..cut.unwrap_or(10000){if receiver.output_ready(){break}let d=match receiver.demands(original.borrow(),4096){Ok(d)=>d,Err(_)=>{refused=true;break}};deny(&mut receiver,original.borrow(),&mut control,&mut bank,d);let g=bank.loan(1,4096);if original_turn(&mut receiver,original.borrow(),&mut control,g,&mut bank).is_err(){refused=true;break}}if cut.is_none(){assert_eq!(receiver.output_ready(),accepted);assert_eq!(refused,!accepted);}if receiver.output_ready(){let output=take(&mut receiver,&mut bank);drain(output,&mut bank);}close(&mut receiver,&mut bank);assert_eq!(crate::observe_retirement_allocations(||drop(receiver)).1,(0,0));drain(original,&mut bank);}}}
